import{_ as a,C as d,o as t,c as i,a0 as r,b as c,w as e,a as n,E as l,a1 as h}from"./chunks/framework.D7EjqxMK.js";const S=JSON.parse('{"title":"06 ROS 2 生态与角色地图","description":"","frontmatter":{},"headers":[],"relativePath":"08-ros/01_基础概念/06_ROS2生态与角色地图.md","filePath":"08-ros/01_基础概念/06_ROS2生态与角色地图.md"}'),p={name:"08-ros/01_基础概念/06_ROS2生态与角色地图.md"};function g(u,o,b,_,m,k){const s=d("Mermaid");return t(),i("div",null,[o[1]||(o[1]=r('<h1 id="_06-ros-2-生态与角色地图" tabindex="-1">06 ROS 2 生态与角色地图 <a class="header-anchor" href="#_06-ros-2-生态与角色地图" aria-label="Permalink to &quot;06 ROS 2 生态与角色地图&quot;">​</a></h1><blockquote><p><strong>在知识图谱中的位置</strong>：模块一 · 基础概念 · 06 <strong>难度</strong>：⭐ | <strong>前置知识</strong>：<a href="./01_什么是ROS2.html">什么是 ROS 2</a></p></blockquote><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><strong>ROS 2 是一个由多家组织、公司、社区共同治理的开源生态：开源基金会与公司承担基础设施，<code>github.com/ros2</code> 组织承载核心代码仓库，<code>index.ros.org</code> 提供包索引，Discourse 是主论坛，ROSCon 是年度大会，贡献流程由 TSC 与 maintainer 制度保障。</strong> 了解这张&quot;角色地图&quot;，才知道该去哪里找包、提问题、提 PR、跟进版本。</p><h2 id="_2-核心概念" tabindex="-1">2. 核心概念 <a class="header-anchor" href="#_2-核心概念" aria-label="Permalink to &quot;2. 核心概念&quot;">​</a></h2><h3 id="_2-1-组织脉络-从-willow-garage-到-open-robotics" tabindex="-1">2.1 组织脉络：从 Willow Garage 到 Open Robotics <a class="header-anchor" href="#_2-1-组织脉络-从-willow-garage-到-open-robotics" aria-label="Permalink to &quot;2.1 组织脉络：从 Willow Garage 到 Open Robotics&quot;">​</a></h3><ul><li><strong>2007</strong>：机器人公司 Willow Garage 启动 ROS 1（ROS 1.0 于 2010 发布）。</li><li><strong>2012</strong>：成立非营利 <strong>OSRF（Open Source Robotics Foundation）</strong>，接管 ROS 的持续开发。</li><li><strong>2017</strong>：OSRF 更名/重组为 <strong>Open Robotics</strong>（旗下含非营利 OSRF 与营利性 OSRC 两部分）。</li><li><strong>2022-12</strong>：Alphabet 旗下 <strong>Intrinsic 收购 OSRC</strong>（Open Robotics 的营利部门），非营利 <strong>OSRF 继续存在</strong>并主导 ROS 开源治理。</li></ul><blockquote><p>这段历史细节以 Open Robotics 官方博客与维基为准；公司层面更名/股权演变的精确表述建议再核对官方公告，本文标注到&quot;2017 重组、2022 Intrinsic 收购&quot;这一公认时间线。</p></blockquote><h3 id="_2-2-代码组织-github-com-ros2" tabindex="-1">2.2 代码组织：<code>github.com/ros2</code> <a class="header-anchor" href="#_2-2-代码组织-github-com-ros2" aria-label="Permalink to &quot;2.2 代码组织：`github.com/ros2`&quot;">​</a></h3><p>核心仓库按&quot;分层&quot;组织，上层依赖下层：</p><table tabindex="0"><thead><tr><th>层</th><th>代表仓库</th><th>作用</th></tr></thead><tbody><tr><td>客户端库</td><td><code>rclcpp</code>、<code>rclpy</code>、<code>rclc</code></td><td>C++/Python/微控制器客户端库</td></tr><tr><td>语言无关核心</td><td><code>rcl</code></td><td>C 语言核心库（<code>rcl_node_t</code> 等句柄）</td></tr><tr><td>中间件抽象</td><td><code>rmw</code>、<code>rmw_cyclonedds</code>、<code>rmw_fastrtps</code></td><td>RMW 接口 + 各 DDS 实现适配</td></tr><tr><td>接口生成</td><td><code>rosidl</code>、<code>rosidl_typesupport</code></td><td><code>.msg/.srv/.action</code> → 各语言</td></tr><tr><td>命令行</td><td><code>ros2cli</code>、<code>ros2launch</code> 等</td><td><code>ros2</code> 命令族</td></tr><tr><td>高层工具</td><td><code>rosbag2</code>、<code>rclcpp_lifecycle</code>、<code>rviz</code></td><td>录制/生命周期/可视化</td></tr></tbody></table><h3 id="_2-3-包分发-index-ros-org" tabindex="-1">2.3 包分发：<code>index.ros.org</code> <a class="header-anchor" href="#_2-3-包分发-index-ros-org" aria-label="Permalink to &quot;2.3 包分发：`index.ros.org`&quot;">​</a></h3><p><code>index.ros.org</code> 是 ROS 的<strong>官方包索引</strong>：能按发行版（jazzy/rolling/...）搜索包，查看其版本、依赖、README、源码/二进制来源。它是&quot;这个包在哪个 distro 里、版本是多少&quot;的权威入口。</p><h3 id="_2-4-社区阵地" tabindex="-1">2.4 社区阵地 <a class="header-anchor" href="#_2-4-社区阵地" aria-label="Permalink to &quot;2.4 社区阵地&quot;">​</a></h3><ul><li><strong>Discourse</strong>：主论坛 <code>discourse.ros.org</code>（现已迁移到 <code>discourse.openrobotics.org</code>），发公告、提问、WG 会议纪要、发布通知都在这。</li><li><strong>ROSCon</strong>：年度 ROS 开发者大会（官网 <code>roscon.ros.org</code>），含技术演讲、Lightning talk、厂商展区。⚠️ <code>roscon.global</code> 这一域名<strong>来源待验证</strong>，官方站点以 <code>roscon.ros.org</code> 为准。</li></ul><h2 id="_3-技术原理" tabindex="-1">3. 技术原理 <a class="header-anchor" href="#_3-技术原理" aria-label="Permalink to &quot;3. 技术原理&quot;">​</a></h2><h3 id="_3-1-一条-ros2-topic-list-命令的调用链-源码级" tabindex="-1">3.1 一条 <code>ros2 topic list</code> 命令的调用链（源码级） <a class="header-anchor" href="#_3-1-一条-ros2-topic-list-命令的调用链-源码级" aria-label="Permalink to &quot;3.1 一条 `ros2 topic list` 命令的调用链（源码级）&quot;">​</a></h3><p>以 <code>ros2cli</code> 仓库为例，理解生态的&quot;可扩展 CLI 架构&quot;：</p><ol><li>入口 <code>ros2</code> 是 <code>ros2cli</code> 提供的<strong>命令分派器</strong>，按第一个词（verb）加载对应子命令插件。</li><li><code>ros2 topic list</code> 进入 <code>ros2topic</code> 包的 <code>ros2topic/command/topic.py</code> 与 <code>verb/list.py</code>。</li><li><code>list.py</code> 通过 <code>rclpy</code> 的 <strong>graph API</strong>（<code>rclpy</code> 内部调用 <code>rcl</code> 的 <code>rcl_get_topic_names_and_types()</code>，再经 <code>rmw</code> 查询 DDS 发现缓存）拿到话题名与类型。</li><li>结果格式化打印到终端。</li></ol><p><strong>关键点</strong>：这条链展示了 ROS 2 生态的<strong>插件化设计</strong>——第三方完全可以新增自己的 <code>ros2 xxx</code> 子命令（放在包的 <code>entry_points</code> 里注册 verb），无需修改 <code>ros2cli</code> 本体。<code>rcl_get_topic_names_and_types()</code> 是 <code>rcl/graph.h</code> 中的真实函数，是&quot;图自省（introspection）&quot;能力的源码锚点。</p><h3 id="_3-2-治理与发布数据流" tabindex="-1">3.2 治理与发布数据流 <a class="header-anchor" href="#_3-2-治理与发布数据流" aria-label="Permalink to &quot;3.2 治理与发布数据流&quot;">​</a></h3>',21)),(t(),c(h,null,{default:e(()=>[l(s,{id:"mermaid-194",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22%E8%B4%A1%E7%8C%AE%E8%80%85%20PR%22%5D%20--%3E%20B%5B%22%E5%8C%85%20maintainer%20review%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%E5%90%88%E5%B9%B6%E5%88%B0%20ros2%2F%3Crepo%3E%20%E7%9B%AE%E6%A0%87%E5%88%86%E6%94%AF%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22ros%2Frosdistro%20%E7%9A%84%20distribution.yaml%20%E8%AE%B0%E5%BD%95%E7%89%88%E6%9C%AC%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22ROS%20buildfarm%20%E4%BA%A4%E5%8F%89%E7%BC%96%E8%AF%91%2F%E6%B5%8B%E8%AF%95%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22%E5%8F%91%E5%B8%83%E5%88%B0%20apt%20%E6%BA%90%20%2B%20index.ros.org%22%5D%0A"})]),fallback:e(()=>[...o[0]||(o[0]=[n(" Loading... ",-1)])]),_:1})),o[2]||(o[2]=r(`<ul><li><strong>TSC（Technical Steering Committee）</strong>：裁决技术方向与争议，章程见 docs.ros.org 的 Governance 页。</li><li><strong>Working Groups</strong>：如 Middleware WG、Real-Time WG、Security WG、Client Libraries WG、Tooling WG 等，分领域推进设计评审（完整列表见官方 Working Groups 页，名单随项目演进）。</li><li><strong>maintainer</strong>：每个包的代码/发布负责人，PR 需其 review 通过。</li></ul><h2 id="_4-实践指南" tabindex="-1">4. 实践指南 <a class="header-anchor" href="#_4-实践指南" aria-label="Permalink to &quot;4. 实践指南&quot;">​</a></h2><h3 id="_4-1-找包、装包、贡献的最小闭环" tabindex="-1">4.1 找包、装包、贡献的最小闭环 <a class="header-anchor" href="#_4-1-找包、装包、贡献的最小闭环" aria-label="Permalink to &quot;4.1 找包、装包、贡献的最小闭环&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1) 找包：在 index.ros.org 搜 &quot;demo_nodes_cpp&quot;，确认它在 jazzy 有二进制</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2) 装包（Ubuntu）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ros-jazzy-demo-nodes-cpp</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3) 本地跑</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/ros/jazzy/setup.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo_nodes_cpp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> talker</span></span></code></pre></div><h3 id="_4-2-贡献-pr-的流程" tabindex="-1">4.2 贡献 PR 的流程 <a class="header-anchor" href="#_4-2-贡献-pr-的流程" aria-label="Permalink to &quot;4.2 贡献 PR 的流程&quot;">​</a></h3><ol><li>找到目标仓库（<code>github.com/ros2/&lt;repo&gt;</code>），读 <code>CONTRIBUTING.md</code>。</li><li>Fork → 建分支 → 修改 → 提交（遵循 DCO sign-off：<code>git commit -s</code>）。</li><li>跑测试与 linter（<code>colcon test</code>、<code>ament_lint</code>），确保 CI 绿。</li><li>提 PR，@ 相关 maintainer，在 Discourse 相关 WG 帖子里说明动机。</li><li>等 review，按意见迭代；合并后走 release 流程进入某个 distro。</li></ol><h3 id="_4-3-常见陷阱" tabindex="-1">4.3 常见陷阱 <a class="header-anchor" href="#_4-3-常见陷阱" aria-label="Permalink to &quot;4.3 常见陷阱&quot;">​</a></h3><table tabindex="0"><thead><tr><th>坑</th><th>现象</th><th>解法</th></tr></thead><tbody><tr><td>在 GitHub 上&quot;乱找&quot;核心包</td><td>分不清 rcl/rclcpp/rmw 层级</td><td>按上文分层表定位仓库</td></tr><tr><td>把 Discourse 当 GitHub issue 用</td><td>问题无人跟进</td><td>代码 bug 提 issue/PR，讨论去 Discourse</td></tr><tr><td>用错发行版搜包</td><td>index 上找不到包</td><td>切换 index 的 distro 过滤为 jazzy 等</td></tr><tr><td>直接抄第三方博客里的旧命令</td><td>命令/URL 已失效</td><td>以 docs.ros.org 当前发行版为准</td></tr></tbody></table><h3 id="_4-4-注意事项" tabindex="-1">4.4 注意事项 <a class="header-anchor" href="#_4-4-注意事项" aria-label="Permalink to &quot;4.4 注意事项&quot;">​</a></h3><ul><li>ROS 2 核心仓库众多，入门不必全读：先认准 <code>rclcpp</code>/<code>rclpy</code>/<code>rcl</code>/<code>rmw</code>/<code>rosidl</code>/<code>ros2cli</code> 六个&quot;骨架&quot;。</li><li>官方二进制包的权威来源是 <code>packages.ros.org</code> 与 <code>index.ros.org</code>；<strong>不要从不明第三方源安装 ROS 包</strong>。</li><li>关注发行版发布公告（Discourse 的 &quot;ROS Announcements&quot;），跟进 EOL 与迁移窗口。</li></ul><h2 id="_5-方案对比" tabindex="-1">5. 方案对比 <a class="header-anchor" href="#_5-方案对比" aria-label="Permalink to &quot;5. 方案对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>优势</th><th>劣势</th><th>适用场景</th></tr></thead><tbody><tr><td>官方核心（github.com/ros2）</td><td>权威、受 TSC 治理</td><td>迭代节奏按社区</td><td>核心能力</td></tr><tr><td>第三方生态包（导航/控制等）</td><td>功能丰富</td><td>质量/维护参差</td><td>具体功能</td></tr><tr><td>商业发行版（各厂商维护的 ROS 2）</td><td>认证、技术支持</td><td>锁定、成本</td><td>量产/安全认证</td></tr><tr><td>自研 fork</td><td>完全可控</td><td>维护成本极高、脱离生态</td><td>极特殊定制</td></tr></tbody></table><blockquote><p><strong>在什么场景下绝对不能使用</strong>：<strong>绝不能从 GitHub 的 <code>master</code>/<code>rolling</code> 分支直接拉取未发布代码并部署到生产机器人</strong>——这些分支处于持续集成中、可能不通过 release 测试；生产必须使用经 ROS buildfarm 测试、冻结的发行版二进制（如 jazzy），或经完整 CI 验证的固定 commit。</p></blockquote><h2 id="_6-工具链" tabindex="-1">6. 工具链 <a class="header-anchor" href="#_6-工具链" aria-label="Permalink to &quot;6. 工具链&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>用途</th><th>链接</th></tr></thead><tbody><tr><td>index.ros.org</td><td>官方包索引</td><td><a href="https://index.ros.org" target="_blank" rel="noreferrer">https://index.ros.org</a></td></tr><tr><td>Discourse</td><td>社区论坛</td><td><a href="https://discourse.openrobotics.org" target="_blank" rel="noreferrer">https://discourse.openrobotics.org</a></td></tr><tr><td>ROSCon</td><td>年度大会</td><td><a href="https://roscon.ros.org" target="_blank" rel="noreferrer">https://roscon.ros.org</a></td></tr><tr><td>ros/rosdistro</td><td>发行版元数据（distribution.yaml）</td><td><a href="https://github.com/ros/rosdistro" target="_blank" rel="noreferrer">https://github.com/ros/rosdistro</a></td></tr><tr><td>build.ros.org</td><td>ROS buildfarm</td><td><a href="https://build.ros.org" target="_blank" rel="noreferrer">https://build.ros.org</a></td></tr></tbody></table><h2 id="_7-参考资料" tabindex="-1">7. 参考资料 <a class="header-anchor" href="#_7-参考资料" aria-label="Permalink to &quot;7. 参考资料&quot;">​</a></h2><ul><li>ROS 2 官方文档（Jazzy）：<a href="https://docs.ros.org/en/jazzy/" target="_blank" rel="noreferrer">https://docs.ros.org/en/jazzy/</a> ✅已验证</li><li>Open Robotics（历史）：<a href="https://en.wikipedia.org/wiki/Open_Robotics" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/Open_Robotics</a> ✅已验证</li><li>Intrinsic 收购 OSRC：<a href="https://www.openrobotics.org/blog/2022/12/15/intrinsic-acquires-osrc-and-osrc-sg" target="_blank" rel="noreferrer">https://www.openrobotics.org/blog/2022/12/15/intrinsic-acquires-osrc-and-osrc-sg</a> ✅已验证</li><li>github.com/ros2 组织：<a href="https://github.com/ros2" target="_blank" rel="noreferrer">https://github.com/ros2</a> ✅已验证</li><li>Middleware Working Group：<a href="https://github.com/ros2/middleware_working_group" target="_blank" rel="noreferrer">https://github.com/ros2/middleware_working_group</a> ✅已验证</li><li>Working Groups 治理页：<a href="https://docs.ros.org/en/jazzy/The-ROS2-Project/Governance/Working-Groups.html" target="_blank" rel="noreferrer">https://docs.ros.org/en/jazzy/The-ROS2-Project/Governance/Working-Groups.html</a> ✅已验证</li><li>TSC 章程：<a href="https://docs.ros.org/en/galactic/The-ROS2-Project/Governance/ROS2-TSC-Charter.html" target="_blank" rel="noreferrer">https://docs.ros.org/en/galactic/The-ROS2-Project/Governance/ROS2-TSC-Charter.html</a> ✅已验证</li><li>ROS 包索引：<a href="https://index.ros.org" target="_blank" rel="noreferrer">https://index.ros.org</a> ✅已验证</li><li>ROS Discourse：<a href="https://discourse.openrobotics.org" target="_blank" rel="noreferrer">https://discourse.openrobotics.org</a> ✅已验证（原 <code>discourse.ros.org</code> 已迁移至此）</li><li>ROSCon：<a href="https://roscon.ros.org" target="_blank" rel="noreferrer">https://roscon.ros.org</a> ✅已验证（<code>roscon.global</code> ⚠️来源待验证）</li><li>rosdistro 仓库：<a href="https://github.com/ros/rosdistro" target="_blank" rel="noreferrer">https://github.com/ros/rosdistro</a> ✅已验证</li></ul><h2 id="_8-学习路径" tabindex="-1">8. 学习路径 <a class="header-anchor" href="#_8-学习路径" aria-label="Permalink to &quot;8. 学习路径&quot;">​</a></h2><ul><li><strong>Level 1</strong>：浏览 index.ros.org，搜出 <code>demo_nodes_cpp</code> 在 jazzy 的版本。</li><li><strong>Level 2</strong>：逛 Discourse 的 Announcements/General 板块，读一篇发行版发布帖。</li><li><strong>Level 3</strong>：在 github.com/ros2 里认全 rcl/rclcpp/rmw/rosidl/ros2cli 五层仓库。</li><li><strong>Level 4</strong>：给某包提一个文档/小 bug 的 PR，走完 DCO + review 流程。</li><li><strong>Level 5</strong>：参与某个 Working Group 的设计讨论，理解 TSC 决策与 release 流程。</li></ul><h2 id="_9-核心面试三问" tabindex="-1">9. 核心面试三问 <a class="header-anchor" href="#_9-核心面试三问" aria-label="Permalink to &quot;9. 核心面试三问&quot;">​</a></h2><p><strong>Q1：Open Robotics、OSRF、Intrinsic 三者现在是什么关系？</strong></p><p>参考要点：OSRF 是 2012 年成立的<strong>非营利基金会</strong>，2017 年重组为 Open Robotics（含非营利 OSRF 与营利 OSRC）；2022 年 Intrinsic 收购了营利性 OSRC，非营利 OSRF 继续存在并主导 ROS 开源治理。三者不是同一实体，谈&quot;谁拥有 ROS&quot;时要区分营利/非营利两部分。</p><p><strong>Q2：一个第三方包是怎么&quot;进入&quot; jazzy 发行版、变成 <code>apt install ros-jazzy-xxx</code> 的？</strong></p><p>参考要点：包在 GitHub 上由 maintainer 维护 → 其版本被登记进 <code>ros/rosdistro</code> 的 <code>jazzy/distribution.yaml</code> → ROS buildfarm 按该元数据拉源码交叉编译/跑测试 → 产物发布到 <code>packages.ros.org</code> 源，<code>index.ros.org</code> 同步展示。<strong>直接有 GitHub 仓库 ≠ 进了发行版</strong>。</p><p><strong>Q3：<code>rcl</code>、<code>rclcpp</code>、<code>rmw</code> 三个仓库的分工与依赖方向是什么？为什么这样分层？</strong></p><p>参考要点：<code>rmw</code> 定义语言无关的中间件抽象（对接 DDS）；<code>rcl</code> 在 rmw 之上实现语言无关的节点/话题/图 API（<code>rcl_node_t</code>、<code>rcl_get_topic_names_and_types</code>）；<code>rclcpp</code> 在 rcl 之上提供 C++ 面向对象封装（<code>rclcpp::Node</code>）。依赖方向 rclcpp→rcl→rmw，好处是换 DDS 后端只动 rmw 实现，上层（rclcpp/rclpy）零改动，实现&quot;客户端库与通信后端解耦&quot;。</p>`,26))])}const q=a(p,[["render",g]]);export{S as __pageData,q as default};
